bounded_host_request.command:
set -euo pipefail
wget_ok=0
if docker run --rm --network host --pull never --entrypoint /bin/sh create-videobot:local-poll -c 'wget -T 8 -q -O /dev/null https://api.telegram.org' >/dev/null 2>&1;then wget_ok=1;fi
node_ok=0
if docker run --rm --network host --pull never --entrypoint node create-videobot:local-poll --input-type=module -e '
import https from "node:https";
const req=https.get("https://api.telegram.org",{family:4,timeout:8500},r=>{r.resume();r.on("end",()=>{process.exitCode=0})});
req.on("timeout",()=>{req.destroy();process.exitCode=1});
req.on("error",()=>{process.exitCode=1});
' >/dev/null 2>&1;then node_ok=1;fi
if test "$node_ok" = 1;then exit 0;fi
if test "$wget_ok" = 1;then exit 80;fi
exit 81
